Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PECRS3U.
Import PMU.
Abbreviation CAD := PeCLayoutU.CADDR_U.
Local Ltac lia := PMK.alia.     (* [comment removed for export] *)
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation T3 := PMSP.T3.
Abbreviation T4 := PMSP.T4.
Ltac kept_tac KS KP := intros x Hx; rewrite (KS x) by (revert x Hx; apply PECSRK.sub_in; vm_compute; reflexivity); apply KP; exact Hx.

Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Let KL := PECKU.klayout_U L LY.
Let SF := PECKU.sfoot_U L LY.

Section Call.
Variables (R0 : bvmap 5 word) (M0 : word -> option byte) (model0 : Model) (K : TSet) (LBX : list (Z * Z)) (cr0 : credit).
Variables (S r fb len : Z) (s0 : PM.pst) (str : PM.vstr) (sm0 : PM.strm).
Variable pl : list Z.   (* [comment removed for export] *)
Hypothesis Rra0 : getr R0 (reg 1) = Z_to_bv 64 r.
Hypothesis RAok : L5.ra_ok r.
Hypothesis Rsp0 : getr R0 (reg 2) = Z_to_bv 64 S.
Hypothesis Rgp0 : getr R0 (reg 3) = Z_to_bv 64 (pa_gp CAD).
Hypothesis Rtp0 : getr R0 (reg 4) = Z_to_bv 64 (pa_tp CAD).
Hypothesis K0 : K [].
Hypothesis FR1 : S <= fb.
Hypothesis FR2 : fb + 832 <= hl_sptop L.
Hypothesis FR3 : fb mod 16 = 0.
Hypothesis Hlen : 0 <= len < 2 ^ 64.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis UN0 : PM.unread (PM.p_src s0) sm0 < 2 ^ 26.
Hypothesis POK : PECS.payload_ok pl.
Hypothesis FBS : PECSU.fill_buffer_spec L HI.
Hypothesis SRDS : PECTXS.csrd_read_spec RSEGS CAD L HI.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (s' : PM.pst) (sm' : PM.strm) (cr' : credit) (ptr n : Z),
  regs_preserved R0 R' -> getr R' 10%bv = Z_to_bv 64 ptr -> getr R' 11%bv = Z_to_bv 64 n -> 0 <= n <= len -> n < 2 ^ 26 ->
  ((ptr = 0 /\ n = 0) \/ (exists B m, In (B, m) (PM.parser_own s') /\ B <= ptr /\ ptr + n <= B + m) \/ (PMSP.o_tb CAD fb + 1 <= ptr /\ ptr + n <= PMSP.o_tb CAD fb + 24)) ->
  L5.defined M' ptr n ->
  L5.bytes_at RSEGS M' ptr (UbjRef.slice pl (PEC.pos_of pl (PM.p_src s0) sm0) n) -> n = Z.min len (blen pl - PEC.pos_of pl (PM.p_src s0) sm0) ->
  PM.parser_at RSEGS CAD T3 T4 M' (PMSP.o_p CAD fb) (PMSP.o_is CAD fb) s' -> PM.iss_at RSEGS CAD T3 M' (PMSP.o_is CAD fb) str sm' -> PM.tb_ok (PM.p_tb s') (PM.p_tg s') ->
  PEC.content_ok RSEGS CAD M' fb pl (PM.p_src s') str sm' ->
  PM.p_more s' = PM.p_more s0 -> PM.p_done s' = PM.p_done s0 -> PM.p_depth s' = PM.p_depth s0 ->
  PM.p_b s' = PM.p_b s0 -> PM.p_k s' = PM.p_k s0 -> PM.p_stk s' = PM.p_stk s0 ->
  PMSP.src_step (PM.p_src s0) (PM.p_src s') sm0 sm' -> PMSP.consumed (PM.p_src s0) (PM.p_src s') sm0 sm' = n ->
  L5C.hpres L LBX S (PMSP.pm_scr 6) (PMSP.W_srcf CAD fb ++ [(PMSP.o_tb CAD fb, 24)]) M0 M' ->
  PMSP.credit_keep cr0 cr' (PM.pot_text L (PM.p_tb s0) (PM.p_tg s0)) (PM.pot_text L (PM.p_tb s') (PM.p_tg s')) ->
  model_but_vm model0 model' -> hi_heap HI (PM.parser_own s' ++ LBX) cr' M' (m_vmmaps model') ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.

#[local] Abbreviation W0 := (PECRS1U.W0 fb).
#[local] Abbreviation saves4 := (PECRS1U.saves4 R0 S).
